package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.village.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes;
public final class VillagePopulationScaleGameTest{@GameTest public void fortyVillagersAreObserved(GameTestHelper c){for(int i=0;i<40;i++)c.spawn(EntityTypes.VILLAGER,2+(i%8),1,2+(i/8));c.runAtTickTime(2,()->{long start=System.nanoTime();TheWorldRemembers.processWorld(c.getLevel());long elapsed=(System.nanoTime()-start)/1_000_000;int population=VillageManager.get(c.getLevel().getServer()).all().stream().mapToInt(VillageState::population).sum();if(population<40){c.fail("Population undercount: "+population);return;}if(elapsed>3000){c.fail("Village observation exceeded 3s: "+elapsed+"ms");return;}c.succeed();});}}
